export type DistrictShape = {
  district: DistrictNumber;
  /** SVG path data in DISTRICT_VIEWBOX units; render with fill-rule="evenodd". */
  path: string;
  /** Label anchor (pole of inaccessibility of the district's main ring). */
  centroid: [number, number];
};

